INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 23, 'theory', 'Quiz: the DOM tree');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 23, 0, 'How do children and childNodes differ?', '["They do not", "children has only elements, childNodes has all nodes, including text and comments", "childNodes has only elements", "children includes attributes"]', 1, 'Whitespace between tags forms text nodes, so the first node in childNodes is often text.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 23, 1, 'How do you safely put user input on the page?', '["el.textContent = input", "el.innerHTML = input", "document.write(input)", "eval(input)"]', 0, 'textContent inserts plain text: angle brackets do not turn into tags, so a script cannot be injected.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 23, 2, 'What does element.closest(''form'') return?', '["The first descendant form", "All forms in the document", "The next sibling", "The nearest ancestor (including the element itself) that matches the selector, or null"]', 3, 'closest climbs up through the ancestors; it is the basis of event delegation.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 23, 3, 'Why is <button disabled="false"> still disabled?', '["Because of a browser bug", "Because false is the string \"true\"", "Boolean attributes work by presence, not by value", "Because disabled is a style property"]', 2, 'You can enable the button by setting the property btn.disabled = false or by removing the attribute.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 23, 4, 'How does querySelectorAll differ from getElementsByClassName?', '["querySelectorAll is always faster", "The result of querySelectorAll is a static snapshot, while getElementsByClassName is a live collection", "Both are live", "Both return a single element"]', 1, 'A live collection updates when the tree changes, so it is better to convert it to an array before looping.');
